begin;
create temp table portal_test_ids as select gen_random_uuid() owner_id,gen_random_uuid() coach_id,gen_random_uuid() parent_a,gen_random_uuid() parent_b,gen_random_uuid() child_a,gen_random_uuid() child_b,gen_random_uuid() player_a,gen_random_uuid() player_b,gen_random_uuid() session_a,gen_random_uuid() session_b,gen_random_uuid() task_a,gen_random_uuid() task_b,gen_random_uuid() award_a,gen_random_uuid() award_b,gen_random_uuid() invite_a,gen_random_uuid() group_id;
grant select on portal_test_ids to authenticated;
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data) select id,'authenticated','authenticated',id::text||'@portal-fixture.invalid',now(),'{"role":"owner","player_id":"forged"}'::jsonb from portal_test_ids cross join lateral unnest(array[owner_id,coach_id,parent_a,parent_b,child_a,child_b]) id;
insert into public.staff_members(user_id,role,active) select owner_id,'owner',true from portal_test_ids union all select coach_id,'coach',true from portal_test_ids;
insert into public.coaching_players(id,first_name,last_name,programme,consent_confirmed,consent_recorded_by,created_by) select player_a,'Portal fixture','A','Other',true,owner_id,owner_id from portal_test_ids union all select player_b,'Portal fixture','B','Other',true,owner_id,owner_id from portal_test_ids;
insert into public.guardian_player_links(guardian_id,player_id,approved_by) select parent_a,player_a,owner_id from portal_test_ids union all select parent_b,player_b,owner_id from portal_test_ids;
insert into public.coaching_assignments(player_id,staff_user_id) select player_a,coach_id from portal_test_ids;
insert into public.family_session_schedule(id,player_id,title,starts_at,ends_at,venue,published_by) select session_a,player_a,'Session A',now()+interval '2 hours',now()+interval '3 hours','Pitch A',owner_id from portal_test_ids union all select session_b,player_b,'Session B',now()+interval '2 hours',now()+interval '3 hours','Pitch B',owner_id from portal_test_ids;
insert into public.player_training_assignments(id,player_id,title,instructions,created_by) select task_a,player_a,'Task A','Fixture practice instructions',owner_id from portal_test_ids union all select task_b,player_b,'Task B','Other practice instructions',owner_id from portal_test_ids;
insert into public.player_space_profiles(player_id,school,playing_teams,updated_by) select player_a,'PRIVATE SCHOOL A','PRIVATE TEAM A',parent_a from portal_test_ids union all select player_b,'PRIVATE SCHOOL B','PRIVATE TEAM B',parent_b from portal_test_ids;
insert into public.player_achievements(id,player_id,title,description,badge_id,awarded_by) select award_a,player_a,'First Steps','PRIVATE COACH NOTE A','first-steps-bronze',owner_id from portal_test_ids union all select award_b,player_b,'First Steps','PRIVATE COACH NOTE B','first-steps-bronze',owner_id from portal_test_ids;
insert into public.player_sharing_groups(id,name,created_by) select group_id,'Fixture teammates',owner_id from portal_test_ids;
insert into public.player_sharing_members(group_id,player_id) select group_id,player_a from portal_test_ids union all select group_id,player_b from portal_test_ids;
insert into public.player_showcase_settings(player_id,alias,updated_by) select player_b,'Chosen alias B',parent_b from portal_test_ids;
insert into public.player_shared_awards(achievement_id,player_id,shared_by) select award_b,player_b,parent_b from portal_test_ids;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',child_a,'role','authenticated','user_metadata',jsonb_build_object('role','owner','player_id',player_b))::text,true) from portal_test_ids;
do $$ begin
 if exists(select 1 from public.coaching_players where id in(select player_a from portal_test_ids union select player_b from portal_test_ids)) then raise exception 'Unlinked player or forged metadata gained roster access'; end if;
 if exists(select 1 from public.player_space_profiles where player_id in(select player_a from portal_test_ids union select player_b from portal_test_ids)) then raise exception 'Unlinked player read private profiles'; end if;
end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',parent_a,'role','authenticated')::text,true) from portal_test_ids;
insert into public.player_account_invites(id,player_id,player_user_id,guardian_id) select invite_a,player_a,child_a,parent_a from portal_test_ids;
do $$ begin
 begin insert into public.player_account_links(user_id,player_id,approved_by) select child_a,player_a,parent_a from portal_test_ids;raise exception 'Client directly linked a player account';exception when insufficient_privilege then null;end;
 begin insert into public.player_account_invites(player_id,player_user_id,guardian_id) select player_b,child_a,parent_a from portal_test_ids;raise exception 'Parent invited into another child record';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',child_b,'role','authenticated')::text,true) from portal_test_ids;
do $$ begin begin perform public.accept_player_invite(invite_a) from portal_test_ids;raise exception 'Another account accepted invitation';exception when insufficient_privilege then null;end;end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',child_a,'role','authenticated')::text,true) from portal_test_ids;
select public.accept_player_invite(invite_a) from portal_test_ids;
do $$ declare feed_count integer; profile_count integer; begin
 if (select count(*) from public.coaching_players where id in(select player_a from portal_test_ids union select player_b from portal_test_ids))<>1 then raise exception 'Activated player isolation failed'; end if;
 if not exists(select 1 from public.player_space_profiles where player_id=(select player_a from portal_test_ids) and school='PRIVATE SCHOOL A') then raise exception 'Player cannot read own private profile'; end if;
 if exists(select 1 from public.player_space_profiles where player_id=(select player_b from portal_test_ids)) then raise exception 'Player read peer private profile'; end if;
 update public.player_space_profiles set experience='senior',favourite_team='Fixture favourite',updated_by=(select child_a from portal_test_ids) where player_id=(select player_a from portal_test_ids);
 insert into public.player_training_diary(assignment_id,guardian_id,practice_date,minutes,reflection,confidence,enjoyment) select task_a,child_a,(now() at time zone 'Europe/London')::date,15,'Player practice fixture',4,5 from portal_test_ids;
 insert into public.player_personal_goals(player_id,goal,created_by) select player_a,'Player-owned goal fixture',child_a from portal_test_ids;
 insert into public.player_session_preparation(session_id,player_id,help_request,checked_kit,updated_by) select session_a,player_a,'Help with scanning',array['Boots'],child_a from portal_test_ids;
 begin insert into public.player_session_preparation(session_id,player_id,updated_by) select session_b,player_a,child_a from portal_test_ids;raise exception 'Mismatched session/player accepted';exception when insufficient_privilege then null;end;
 insert into public.player_space_messages(player_id,sender_id,sender_role,body) select player_a,child_a,'player','How should I scan before receiving?' from portal_test_ids;
 begin insert into public.player_space_messages(player_id,sender_id,sender_role,body) select player_a,child_a,'coach','Spoofed coach reply' from portal_test_ids;raise exception 'Player impersonated coach';exception when insufficient_privilege then null;end;
 begin insert into public.player_space_messages(player_id,sender_id,sender_role,body) select player_b,child_a,'player','Unrelated player message' from portal_test_ids;raise exception 'Cross-player message accepted';exception when insufficient_privilege then null;end;
 insert into public.player_match_plans(player_id,match_date,checked_items,updated_by) select player_a,current_date,array['kit','water'],child_a from portal_test_ids;
 insert into public.player_match_journal(player_id,match_date,positions,minutes,things_tried,proud_moment,lessons,created_by) select player_a,(now() at time zone 'Europe/London')::date,array['Midfielder'],40,'Scanned before receiving','Encouraged a teammate','Keep looking early',child_a from portal_test_ids;
 begin insert into public.player_match_journal(player_id,match_date,positions,minutes,created_by) select player_a,current_date+3,array['Midfielder'],40,child_a from portal_test_ids;raise exception 'Future match result accepted';exception when check_violation then null;end;
 insert into public.player_learning_progress(player_id,lesson_id,completed_by) select player_a,'positions-goalkeeper',child_a from portal_test_ids;
 insert into public.player_shared_awards(achievement_id,player_id,shared_by) select award_a,player_a,child_a from portal_test_ids;
 select count(*) into feed_count from public.shared_trophy_feed((select player_a from portal_test_ids));if feed_count<>2 then raise exception 'Shared teammate awards not scoped correctly';end if;
 if exists(select 1 from public.shared_trophy_feed((select player_a from portal_test_ids)) f where to_jsonb(f)::text like '%PRIVATE%') then raise exception 'Private school/team/coach note leaked into trophy feed';end if;
 if exists(select 1 from public.player_achievements where id=(select award_b from portal_test_ids)) then raise exception 'Raw teammate coach note exposed';end if;
 begin perform public.shared_trophy_feed(player_b) from portal_test_ids;raise exception 'Player impersonated another feed viewer';exception when insufficient_privilege then null;end;
 begin insert into public.player_sharing_members(group_id,player_id) select group_id,player_a from portal_test_ids;raise exception 'Player changed teammate membership';exception when insufficient_privilege then null;end;
 begin insert into public.player_notifications(player_id,category,title,body,tab,source_key) select player_a,'message','Forged','Fake','messages','forged' from portal_test_ids;raise exception 'Client fabricated a notification';exception when insufficient_privilege then null;end;
 perform public.refresh_session_reminders(player_a) from portal_test_ids;
 if not exists(select 1 from public.player_notifications where player_id=(select player_a from portal_test_ids) and source_key like 'reminder:%') then raise exception 'Session reminder missing';end if;
 insert into public.player_notification_reads(user_id,notification_id) select child_a,n.id from portal_test_ids t join public.player_notifications n on n.player_id=t.player_a limit 1;
 begin insert into public.player_notification_reads(user_id,notification_id) select parent_b,n.id from portal_test_ids t join public.player_notifications n on n.player_id=t.player_a limit 1;raise exception 'Spoofed notification reader accepted';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',parent_a,'role','authenticated')::text,true) from portal_test_ids;
do $$ begin
 if not exists(select 1 from public.player_space_messages where player_id=(select player_a from portal_test_ids) and sender_role='player') then raise exception 'Parent could not see player conversation';end if;
 if not exists(select 1 from public.player_training_diary where assignment_id=(select task_a from portal_test_ids) and guardian_id=(select child_a from portal_test_ids)) then raise exception 'Parent could not see player diary';end if;
 if not exists(select 1 from public.player_match_journal where player_id=(select player_a from portal_test_ids)) then raise exception 'Parent could not view match reflection';end if;
 insert into public.player_space_messages(player_id,sender_id,sender_role,body) select player_a,parent_a,'guardian','Parent-visible reply fixture' from portal_test_ids;
end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',coach_id,'role','authenticated')::text,true) from portal_test_ids;
do $$ begin
 if not exists(select 1 from public.player_session_preparation where player_id=(select player_a from portal_test_ids) and help_request='Help with scanning') then raise exception 'Assigned coach cannot see session help';end if;
 if exists(select 1 from public.player_space_profiles where player_id=(select player_a from portal_test_ids)) then raise exception 'Coach read family-only school profile';end if;
 insert into public.player_space_messages(player_id,sender_id,sender_role,body) select player_a,coach_id,'coach','Try looking over your shoulder before the pass.' from portal_test_ids;
 insert into public.player_coach_notes(player_id,week_start,body,published_by) select player_a,date_trunc('week',current_date)::date,'A personal coaching focus',coach_id from portal_test_ids;
 update public.family_session_schedule set coach_focus='Scan before receiving',kit_list=array['Boots','Water bottle'] where id=(select session_a from portal_test_ids);
 begin update public.family_session_schedule set venue='Unauthorised venue change' where id=(select session_a from portal_test_ids);raise exception 'Coach changed manager-only schedule details';exception when insufficient_privilege then null;end;
 begin insert into public.player_coach_notes(player_id,week_start,body,published_by) select player_b,date_trunc('week',current_date)::date,'Unassigned player note',coach_id from portal_test_ids;raise exception 'Unassigned coach wrote weekly note';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',child_a,'role','authenticated')::text,true) from portal_test_ids;
do $$ begin
 if not exists(select 1 from public.player_notifications where player_id=(select player_a from portal_test_ids) and category='message' and title='A new message from your coach') then raise exception 'Coach reply notification missing';end if;
 if exists(select 1 from public.player_notifications where player_id=(select player_b from portal_test_ids)) then raise exception 'Other player notifications exposed';end if;
end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',parent_a,'role','authenticated')::text,true) from portal_test_ids;
delete from public.player_account_links where player_id=(select player_a from portal_test_ids);
select set_config('request.jwt.claims',jsonb_build_object('sub',child_a,'role','authenticated')::text,true) from portal_test_ids;
do $$ begin
 if star_private.is_player((select player_a from portal_test_ids)) or exists(select 1 from public.coaching_players where id=(select player_a from portal_test_ids)) or exists(select 1 from public.player_space_messages where player_id=(select player_a from portal_test_ids)) then raise exception 'Revoked player retained access with existing auth identity';end if;
end $$;
reset role;
select 'PASS: verified two-party player activation, forged metadata isolation, player/parent/coach scope, parent-visible conversations, private profile projection, session focus restrictions, match and learning records, notifications and immediate access revocation' as result;
rollback;
